export function getWave(waveNumber) {
  const index = Math.max(0, Math.min(WAVES.length - 1, waveNumber - 1));
  const groups = WAVES[index].map((group, i) => ({ ...group, order: i }));
  const spawns = [];
  for (const group of groups) {
    for (let i = 0; i < group.count; i += 1) {
      spawns.push({
        type: group.type,
        at: group.delay + i * group.gap,
        lane: (i % 5) - 2,
      });
    }
  }
  spawns.sort((a, b) => a.at - b.at || a.lane - b.lane);
  const rbe = groups.reduce((sum, group) => {
    const countRbe = balloonRbe(group.type);
    return sum + countRbe * group.count;
  }, 0);
  return {
    number: waveNumber,
    groups,
    spawns,
    duration: spawns.length ? spawns[spawns.length - 1].at : 0,
    rbe,
    reward: 22 + waveNumber * 7,
    boss: groups.some((group) => BALLOON_TYPES[group.type]?.boss),
  };
}

export function balloonRbe(typeId) {
  const type = BALLOON_TYPES[typeId];
  if (!type) return 0;
  return type.hp + type.children.reduce((sum, child) => sum + balloonRbe(child), 0);
}

export function getLeakDamage(typeId) {
  if (typeId === 'moab') return 25;
  return 1;
}

export function formatMoney(value) {
  return value >= 10000 ? `${(value / 1000).toFixed(value >= 100000 ? 0 : 1)}k` : `${Math.floor(value)}`;
}

export function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export function lerp(a, b, t) {
  return a + (b - a) * t;
}

// Tiny synthesized sound engine: no audio files, no autoplay surprises.
export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.master = null;
    this.lastShot = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    this.ctx = new AudioContext();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.16;
    this.master.connect(this.ctx.destination);
  }

  setEnabled(enabled) {
    this.enabled = enabled;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(enabled ? 0.16 : 0, this.ctx.currentTime, 0.03);
    }
  }

  tone(freq, duration, { type = 'sine', volume = 0.3, slide = 0, delay = 0 } = {}) {
    if (!this.enabled || !this.ctx) return;
    const now = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, now);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), now + duration);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain).connect(this.master);
    osc.start(now);
    osc.stop(now + duration + 0.02);
  }

  noise(duration, { volume = 0.25, filter = 800, delay = 0 } = {}) {
    if (!this.enabled || !this.ctx) return;
    const now = this.ctx.currentTime + delay;
    const length = Math.max(1, Math.floor(this.ctx.sampleRate * duration));
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i += 1) {
      data[i] = (Math.random() * 2 - 1) * (1 - i / length) ** 2;
    }
    const source = this.ctx.createBufferSource();
    source.buffer = buffer;
    const biquad = this.ctx.createBiquadFilter();
    biquad.type = 'lowpass';
    biquad.frequency.value = filter;
    const gain = this.ctx.createGain();
    gain.gain.value = volume;
    source.connect(biquad).connect(gain).connect(this.master);
    source.start(now);
  }

  pop(big = false) {
    if (!this.enabled || !this.ctx) return;
    const base = big ? 130 : 280 + Math.random() * 220;
    this.tone(base, big ? 0.24 : 0.08, { type: 'triangle', volume: big ? 0.45 : 0.22, slide: -base * 0.55 });
    this.noise(big ? 0.22 : 0.05, { volume: big ? 0.3 : 0.08, filter: big ? 500 : 1600 });
  }

  shoot(kind = 'dart') {
    if (!this.enabled || !this.ctx) return;
    const now = performance.now();
    if (now - this.lastShot < 42) return;
    this.lastShot = now;
    if (kind === 'sniper') {
      this.tone(190, 0.18, { type: 'sawtooth', volume: 0.32, slide: -100 });
      this.noise(0.12, { volume: 0.18, filter: 1300 });
    } else if (kind === 'bomb') {
      this.tone(110, 0.13, { type: 'square', volume: 0.16, slide: -50 });
    } else if (kind === 'super') {
      this.tone(1050, 0.035, { type: 'square', volume: 0.04, slide: -300 });
    } else if (kind === 'rang') {
      this.tone(520, 0.07, { type: 'triangle', volume: 0.08, slide: 140 });
    } else {
      this.tone(760, 0.045, { type: 'triangle', volume: 0.07, slide: -220 });
    }
  }

  explode() {
    this.noise(0.38, { volume: 0.45, filter: 520 });
    this.tone(70, 0.32, { type: 'sawtooth', volume: 0.4, slide: -38 });
  }

  place() {
    this.tone(340, 0.1, { type: 'triangle', volume: 0.16, slide: 120 });
    this.tone(520, 0.13, { type: 'triangle', volume: 0.12, slide: 160, delay: 0.07 });
  }

  sell() {
    this.tone(620, 0.08, { type: 'triangle', volume: 0.13, slide: -80 });
    this.tone(440, 0.1, { type: 'triangle', volume: 0.1, slide: -80, delay: 0.07 });
  }

  upgrade() {
    [523, 659, 784].forEach((freq, index) => {
      this.tone(freq, 0.16, { type: 'triangle', volume: 0.14, slide: 20, delay: index * 0.065 });
    });
  }

  startWave() {
    [392, 523, 659, 784].forEach((freq, index) => {
      this.tone(freq, 0.3, { type: 'triangle', volume: 0.2, delay: index * 0.075 });
    });
  }

  victory() {
    [523, 659, 784, 1046, 1318].forEach((freq, index) => {
      this.tone(freq, 0.5, { type: 'triangle', volume: 0.2, delay: index * 0.13 });
    });
  }

  defeat() {
    [330, 294, 262, 196].forEach((freq, index) => {
      this.tone(freq, 0.45, { type: 'sawtooth', volume: 0.13, delay: index * 0.16 });
    });
  }

  click() {
    this.tone(660, 0.04, { type: 'triangle', volume: 0.08, slide: 80 });
  }

  alert() {
    this.tone(220, 0.25, { type: 'square', volume: 0.1, slide: 60 });
  }
}

:root {
  --cream: #fff7df;
  --cream-2: #f5e7bf;
  --ink: #1e3222;
  --ink-soft: #4f654b;
  --forest: #153e2c;
  --forest-2: #0c281d;
  --orange: #ff8a2e;
  --orange-dark: #d55a16;
  --gold: #ffd35b;
  --lime: #7ac74f;
  --red: #e94b4f;
  --blue: #3f8ff0;
  --panel-shadow: 0 16px 50px rgba(5, 23, 13, 0.45);
  --outline: rgba(30, 50, 34, 0.2);
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #081d14;
  color: var(--ink);
  font-family: ui-rounded, "Arial Rounded MT Bold", "Trebuchet MS", "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}

body {
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
}

button {
  font: inherit;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

[hidden] {
  display: none !important;
}

.ambient-bg {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 15% 8%, rgba(102, 173, 91, 0.22), transparent 34%),
    radial-gradient(circle at 92% 85%, rgba(235, 156, 56, 0.12), transparent 38%),
    linear-gradient(145deg, #0d271b 0%, #081e15 52%, #06160f 100%);
}

.ambient-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.35;
}

.ambient-glow.one {
  width: 38vw;
  height: 38vw;
  background: #2f7b4a;
  left: -14vw;
  top: -18vw;
}

.ambient-glow.two {
  width: 32vw;
  height: 32vw;
  background: #bd6829;
  right: -12vw;
  bottom: -18vw;
  opacity: 0.16;
}

.ambient-dots {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255, 248, 218, 0.12) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: radial-gradient(circle at center, black, transparent 76%);
}

.app-shell {
  position: relative;
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  padding: 12px;
}

.game-frame {
  position: relative;
  width: min(calc(100vw - 24px), calc((100svh - 24px) * 16 / 9));
  aspect-ratio: 16 / 9;
  max-height: calc(100svh - 24px);
  border-radius: 26px;
  overflow: hidden;
  background: #62a94c;
  box-shadow:
    0 0 0 2px rgba(255, 247, 223, 0.22),
    0 3px 0 rgba(255, 247, 223, 0.08) inset,
    0 32px 90px rgba(0, 0, 0, 0.62);
  isolation: isolate;
}

#gameCanvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
  touch-action: none;
}

/* ---------- Top HUD ---------- */

.topbar {
  position: absolute;
  z-index: 8;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 14px 16px 0;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(13, 43, 29, 0.52), rgba(13, 43, 29, 0));
}

.topbar > * {
  pointer-events: auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-right: 2px;
  flex: 0 0 auto;
  filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.24));
}

.brand-mark {
  position: relative;
  width: 43px;
  height: 52px;
  flex: 0 0 auto;
}

.brand-mark::before {
  content: "";
  position: absolute;
  inset: 0 2px 10px;
  border-radius: 50% 50% 46% 46% / 54% 54% 42% 42%;
  background:
    radial-gradient(circle at 31% 25%, rgba(255, 255, 255, 0.92) 0 8%, transparent 9%),
    radial-gradient(circle at 38% 28%, #ffb5a0 0 17%, transparent 18%),
    linear-gradient(135deg, #ff7b5f, #e43e44 65%, #a81f2e);
  transform: rotate(-5deg);
  box-shadow: 0 4px 0 rgba(97, 18, 30, 0.25);
}

.brand-mark::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 0;
  width: 12px;
  height: 13px;
  transform: translateX(-50%);
  background: #a81f2e;
  clip-path: polygon(12% 0, 88% 0, 100% 100%, 50% 70%, 0 100%);
}

.brand-mark span {
  position: absolute;
  left: 50%;
  bottom: 2px;
  width: 24px;
  height: 18px;
  transform: translateX(-50%);
  border-left: 2px solid rgba(255, 250, 230, 0.8);
  border-radius: 50%;
  opacity: 0.7;
}

.brand-copy {
  color: var(--cream);
  line-height: 0.86;
  transform: translateY(1px);
}

.brand-top {
  font-size: 17px;
  letter-spacing: 0.14em;
  color: #ffd469;
  text-shadow: 0 2px 0 #8e3914;
}

.brand-bottom {
  font-size: 23px;
  letter-spacing: 0.035em;
  text-shadow: 0 3px 0 rgba(70, 34, 11, 0.55);
}

.brand-bottom em {
  font-style: normal;
  font-size: 12px;
  padding: 2px 5px;
  margin-left: 2px;
  border-radius: 5px;
  background: var(--orange);
  color: #fff;
  text-shadow: none;
  vertical-align: 5px;
}

.stat-cluster {
  display: flex;
  align-items: stretch;
  gap: 7px;
  margin-left: 3px;
}

.stat-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 48px;
  min-width: 92px;
  padding: 6px 12px 6px 8px;
  border-radius: 15px;
  background: linear-gradient(180deg, rgba(255, 249, 228, 0.98), rgba(243, 227, 187, 0.96));
  border: 2px solid rgba(77, 59, 31, 0.22);
  box-shadow: 0 4px 0 rgba(70, 51, 26, 0.22), 0 7px 18px rgba(10, 30, 17, 0.18);
}

.stat-chip svg {
  width: 24px;
  height: 24px;
  padding: 3px;
  flex: 0 0 auto;
  border-radius: 50%;
}

.stat-chip.lives svg {
  fill: #e94b4f;
  background: #ffe0d8;
  stroke: #9e2530;
  stroke-width: 1.3;
}

.stat-chip.cash svg {
  fill: #f8c541;
  background: #fff0b8;
  stroke: #9c6712;
  stroke-width: 1.4;
}

.stat-chip.round svg {
  fill: none;
  background: #dff1cd;
  stroke: #376a33;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.stat-copy {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.stat-copy small {
  font-size: 8px;
  letter-spacing: 0.14em;
  color: #8b7551;
  margin-bottom: 4px;
}

.stat-copy strong {
  font-size: 18px;
  letter-spacing: -0.02em;
  color: #28371f;
  font-variant-numeric: tabular-nums;
}

.stat-copy strong i {
  font-style: normal;
  font-size: 9px;
  color: #887755;
  font-weight: 700;
}

.cash .stat-copy strong {
  color: #8f5b08;
}

.round-cluster {
  margin-left: auto;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 5px;
  width: 202px;
  flex: 0 0 auto;
}

.start-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  padding: 5px 14px 5px 9px;
  border: 2px solid #a74812;
  border-radius: 15px;
  background: linear-gradient(180deg, #ffb14a, #f07823 62%, #dd5c17);
  color: #fffdf5;
  cursor: pointer;
  box-shadow: 0 5px 0 #8f3e12, 0 8px 16px rgba(54, 20, 4, 0.3), inset 0 2px 0 rgba(255, 255, 255, 0.35);
  text-shadow: 0 2px 0 rgba(110, 42, 6, 0.45);
  transition: transform 0.12s ease, filter 0.12s ease, box-shadow 0.12s ease;
}

.start-btn:hover:not(:disabled) {
  filter: brightness(1.07);
  transform: translateY(-1px);
  box-shadow: 0 6px 0 #8f3e12, 0 11px 20px rgba(54, 20, 4, 0.3), inset 0 2px 0 rgba(255, 255, 255, 0.35);
}

.start-btn:active:not(:disabled) {
  transform: translateY(3px);
  box-shadow: 0 2px 0 #8f3e12, inset 0 2px 0 rgba(255, 255, 255, 0.25);
}

.start-btn:disabled {
  cursor: default;
  filter: saturate(0.45) brightness(0.85);
  box-shadow: 0 3px 0 #694520, 0 5px 10px rgba(54, 20, 4, 0.25);
}

.start-icon {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: rgba(119, 48, 9, 0.22);
  font-size: 14px;
  padding-left: 2px;
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.16);
}

.start-btn.busy .start-icon {
  animation: busyPulse 1.2s ease-in-out infinite;
}

.start-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1;
}

.start-copy small {
  font-size: 8px;
  letter-spacing: 0.16em;
  opacity: 0.82;
  margin-bottom: 4px;
}

.start-copy strong {
  font-size: 15px;
  letter-spacing: 0.015em;
  white-space: nowrap;
}

.round-meter {
  height: 5px;
  border-radius: 99px;
  background: rgba(18, 46, 28, 0.42);
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.2);
}

.round-meter span {
  display: block;
  width: 0%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ffdd66, #ff8a2e);
  transition: width 0.25s ease;
}

.utility-cluster {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}

.speed-group {
  display: flex;
  padding: 3px;
  border-radius: 13px;
  background: rgba(11, 38, 25, 0.58);
  border: 1px solid rgba(255, 250, 231, 0.2);
  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.18);
}

.speed-btn {
  width: 30px;
  height: 37px;
  padding: 0;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: rgba(255, 249, 229, 0.62);
  font-weight: 900;
  font-size: 12px;
  cursor: pointer;
  transition: background 0.14s, color 0.14s, transform 0.14s;
}

.speed-btn.active {
  background: var(--cream);
  color: #2d481f;
  box-shadow: 0 2px 0 rgba(53, 37, 12, 0.26);
}

.speed-btn:hover:not(.active) {
  color: #fff;
  background: rgba(255, 255, 255, 0.1);
}

.icon-btn {
  position: relative;
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  padding: 0;
  border-radius: 13px;
  border: 1px solid rgba(255, 250, 231, 0.24);
  background: rgba(11, 38, 25, 0.58);
  color: var(--cream);
  font-weight: 900;
  font-size: 16px;
  cursor: pointer;
  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.18);
  transition: background 0.14s, transform 0.14s;
}

.icon-btn:hover {
  background: rgba(255, 249, 228, 0.2);
}

.icon-btn:active {
  transform: translateY(2px);
}

.icon-btn svg {
  width: 22px;
  height: 22px;
  fill: currentColor;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-btn .play-icon,
.icon-btn .sound-off-icon {
  display: none;
}

#pauseBtn.paused .pause-icon {
  display: none;
}

#pauseBtn.paused .play-icon {
  display: block;
}

#soundBtn.muted .sound-on-icon {
  display: none;
}

#soundBtn.muted .sound-off-icon {
  display: block;
}

/* ---------- Boss and hint ---------- */

.boss-banner {
  position: absolute;
  z-index: 7;
  top: 82px;
  left: 50%;
  transform: translate(-50%, -12px);
  opacity: 0;
  padding: 7px 20px;
  border-radius: 99px;
  background: #8f1723;
  border: 2px solid #ffb56f;
  color: #ffeac0;
  font-size: 11px;
  letter-spacing: 0.2em;
  font-weight: 900;
  box-shadow: 0 6px 0 rgba(80, 10, 20, 0.35), 0 10px 22px rgba(0, 0, 0, 0.25);
  pointer-events: none;
  transition: opacity 0.3s, transform 0.3s;
}

.boss-banner.show {
  opacity: 1;
  transform: translate(-50%, 0);
  animation: bossWobble 1.4s ease-in-out infinite;
}

.boss-banner span {
