  height: 26px;
  border-radius: 50%;
  background: #ffcb4d;
  color: #583400;
  flex: 0 0 auto;
  animation: pointBounce 1.4s ease-in-out infinite;
}

/* ---------- Tower panel ---------- */

.tower-panel {
  position: absolute;
  z-index: 9;
  right: 16px;
  top: 82px;
  bottom: 133px;
  width: 286px;
  display: flex;
  flex-direction: column;
  padding: 14px;
  border-radius: 20px;
  border: 2px solid rgba(92, 64, 30, 0.32);
  background:
    linear-gradient(180deg, rgba(255, 250, 232, 0.98), rgba(244, 230, 194, 0.98));
