  font-size: 7px;
  letter-spacing: 0.08em;
  color: #927e5b;
  font-weight: 900;
}

.panel-stats strong {
  font-size: 12px;
  color: #39462b;
  font-variant-numeric: tabular-nums;
}

.target-row {
  display: flex;
  align-items: center;
  gap: 3px;
  margin-bottom: 8px;
}

.target-row > span {
  margin-right: auto;
  font-size: 8px;
  letter-spacing: 0.12em;
  color: #927e5b;
  font-weight: 900;
}

.target-row button {
  padding: 4px 6px;
  border: 0;
  border-radius: 6px;
  background: rgba(65, 82, 44, 0.07);
  color: #7d6b4b;
  font-size: 8px;
  font-weight: 900;
  cursor: pointer;
}

.target-row button.active {
  background: #435d31;
  color: #fff9e4;
}

.upgrade-list {
  display: grid;
  gap: 7px;
  min-height: 0;
  overflow: auto;
  padding: 1px 2px 6px 0;
  scrollbar-width: thin;
}

.upgrade {
  position: relative;
  display: grid;
  grid-template-columns: 25px 1fr auto;
  align-items: center;
  gap: 7px;
  padding: 7px 8px;
  border: 1px solid rgba(70, 88, 47, 0.14);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.45);
  text-align: left;
  cursor: pointer;
  transition: transform 0.12s, background 0.12s;
}

.upgrade:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.82);
  transform: translateY(-1px);
}

.upgrade.path-top .upgrade-icon {
  background: #f9c550;
  color: #724005;
}

.upgrade.path-bottom .upgrade-icon {
  background: #75bce3;
  color: #154a64;
}

.upgrade-icon {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 900;
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.4);
}

.upgrade-copy {
  min-width: 0;
}

.upgrade-copy strong {
  display: block;
  font-size: 10px;
  color: #364324;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.upgrade-copy small {
  display: block;
  margin-top: 2px;
  font-size: 8px;
  line-height: 1.2;
  color: #877653;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.upgrade-cost {
  padding: 3px 6px;
  border-radius: 6px;
  background: #fff3c6;
  color: #8b5d08;
  font-size: 9px;
  font-weight: 900;
  white-space: nowrap;
}

.upgrade:disabled {
  cursor: default;
  opacity: 0.48;
}

.upgrade.maxed .upgrade-cost {
  background: #d9ead0;
  color: #53773f;
}

.sell-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-top: auto;
  padding: 7px 10px;
  border: 1px solid rgba(127, 50, 36, 0.18);
  border-radius: 9px;
  background: rgba(179, 67, 52, 0.08);
  color: #8e3b32;
  font-size: 10px;
  font-weight: 900;
  cursor: pointer;
}

.sell-btn:hover {
  background: rgba(179, 67, 52, 0.15);
}

.sell-btn strong {
  color: #7b311f;
}

/* ---------- Shop ---------- */

.shop-dock {
  position: absolute;
  z-index: 8;
  left: 16px;
  right: 16px;
  bottom: 12px;
  height: 108px;
  display: flex;
  align-items: stretch;
  gap: 10px;
  padding: 9px 10px;
  border-radius: 21px;
  border: 2px solid rgba(255, 241, 197, 0.25);
  background:
    linear-gradient(180deg, rgba(29, 65, 40, 0.94), rgba(13, 42, 27, 0.97));
  box-shadow:
    0 16px 38px rgba(6, 20, 12, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(12px);
}

.shop-label {
  display: flex;
  flex-direction: column;
  justify-content: center;
  width: 82px;
  padding-left: 6px;
  flex: 0 0 auto;
  color: #ffe9ae;
  line-height: 1;
}

.shop-label span {
  font-size: 8px;
  letter-spacing: 0.22em;
  opacity: 0.6;
}

.shop-label strong {
  margin: 3px 0 5px;
  font-size: 15px;
  letter-spacing: 0.02em;
  color: #fff4ce;
}

.shop-label small {
  font-size: 8px;
  color: rgba(255, 244, 206, 0.42);
}

.shop {
  display: flex;
  align-items: stretch;
  gap: 6px;
  flex: 1 1 auto;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 1px;
  scrollbar-width: none;
}

.shop::-webkit-scrollbar {
  display: none;
}

.shop-card {
  position: relative;
  display: grid;
  grid-template-columns: 47px 1fr;
  align-items: center;
  gap: 4px;
  min-width: 118px;
  flex: 1 1 118px;
  padding: 5px 8px 6px 4px;
  border: 2px solid rgba(71, 53, 24, 0.25);
  border-radius: 14px;
  background: linear-gradient(180deg, #fff8e5, #efdfb9);
  color: #3e4b29;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 3px 0 rgba(49, 34, 13, 0.24);
  transition: transform 0.13s, box-shadow 0.13s, filter 0.13s;
  overflow: hidden;
}

.shop-card::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 3px;
  background: var(--tower-color, #75bd50);
  opacity: 0.7;
}

.shop-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 0 rgba(49, 34, 13, 0.20), 0 9px 14px rgba(0, 0, 0, 0.16);
}

.shop-card.selected {
  transform: translateY(-3px);
  border-color: #ffd05b;
  background: linear-gradient(180deg, #fffdf1, #ffe8a8);
  box-shadow: 0 0 0 3px rgba(255, 205, 81, 0.26), 0 5px 0 #9d6812, 0 10px 18px rgba(0, 0, 0, 0.2);
}

.shop-card.unaffordable .shop-cost {
  color: #c04a35;
  background: #ffe0d5;
}

.shop-card.unaffordable .shop-thumb {
  filter: saturate(0.55);
}

.shop-thumb {
  width: 47px;
  height: 47px;
  display: block;
  border-radius: 12px;
  background:
    radial-gradient(circle at 35% 28%, rgba(255, 255, 255, 0.9), transparent 48%),
    rgba(122, 166, 80, 0.2);
}

.shop-copy {
  min-width: 0;
  line-height: 1;
}

.shop-copy strong {
  display: block;
  font-size: 9px;
  letter-spacing: 0.01em;
  line-height: 1.06;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.shop-copy small {
  display: block;
  margin-top: 3px;
  font-size: 7px;
  color: #8d7d5c;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.shop-cost {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin-top: 5px;
  padding: 2px 5px;
  border-radius: 5px;
  background: #f9e8a9;
  color: #855600;
  font-size: 9px;
  font-weight: 900;
}

.shop-cost::before {
  content: "$";
  opacity: 0.7;
}

.shop-key {
  position: absolute;
  right: 4px;
  top: 3px;
  font-size: 7px;
  color: rgba(63, 76, 43, 0.42);
  font-weight: 900;
}

.shop-status {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 131px;
  flex: 0 0 auto;
  padding: 0 4px;
  border-left: 1px solid rgba(255, 245, 208, 0.12);
  color: rgba(255, 246, 218, 0.62);
  font-size: 9px;
  line-height: 1.2;
  font-weight: 700;
}

.status-dot {
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #7ed75c;
  box-shadow: 0 0 8px #7ed75c;
  animation: statusPulse 2s ease-in-out infinite;
}

/* ---------- Feedback ---------- */

.toast {
  position: absolute;
  z-index: 12;
  left: 50%;
  top: 92px;
  transform: translate(-50%, -8px);
  max-width: 460px;
  padding: 8px 16px;
  border-radius: 10px;
  background: #fff8df;
  color: #3b4b2b;
  border: 1px solid rgba(43, 65, 29, 0.2);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.24);
  font-size: 11px;
  font-weight: 800;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast.error {
  background: #ffe4d8;
  color: #8d3026;
  border-color: #c85b47;
}

.round-flash {
  position: absolute;
  z-index: 11;
  left: 50%;
  top: 44%;
  transform: translate(-50%, -50%) scale(0.7);
  display: flex;
  flex-direction: column;
  align-items: center;
  color: #fff6cf;
  text-shadow: 0 5px 0 #7a3b0d, 0 10px 28px rgba(0, 0, 0, 0.5);
  opacity: 0;
  pointer-events: none;
}

.round-flash small {
  font-size: 13px;
  letter-spacing: 0.45em;
  font-weight: 900;
}

.round-flash strong {
  font-size: 74px;
  line-height: 0.95;
  letter-spacing: -0.05em;
}

.round-flash.pop {
  animation: roundFlash 1.5s ease-out both;
}

/* ---------- Menu and modals ---------- */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 22px;
}

.menu-screen {
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 34%, rgba(24, 66, 39, 0.22), rgba(5, 20, 13, 0.7) 70%),
    linear-gradient(180deg, rgba(9, 27, 18, 0.28), rgba(4, 15, 10, 0.78));
  backdrop-filter: blur(3px);
  transition: opacity 0.35s ease, visibility 0.35s;
}

.menu-screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.menu-card {
  position: relative;
  width: min(492px, calc(100vw - 32px));
  padding: 34px 52px 26px;
  border-radius: 34px;
  border: 3px solid #72532a;
  background:
    radial-gradient(circle at 21% 13%, rgba(255, 255, 255, 0.7), transparent 18%),
    linear-gradient(155deg, #fff9e4 0%, #f6e5b9 55%, #edcf91 100%);
  box-shadow:
    0 7px 0 #4d3519,
    0 18px 0 rgba(30, 22, 9, 0.18),
    0 32px 90px rgba(0, 0, 0, 0.55),
    inset 0 2px 0 rgba(255, 255, 255, 0.8);
  text-align: center;
  animation: menuCardIn 0.6s cubic-bezier(0.18, 0.9, 0.3, 1.15) both;
}

.menu-card::before,
.menu-card::after {
  content: "";
  position: absolute;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #b58c43;
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.4), 0 2px 0 rgba(80, 52, 15, 0.4);
}

.menu-card::before {
  left: 16px;
  top: 16px;
}

.menu-card::after {
  right: 16px;
  bottom: 16px;
}

.menu-eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 11px;
  font-size: 8px;
  letter-spacing: 0.22em;
  color: #927344;
  font-weight: 900;
}

.menu-eyebrow span {
  width: 24px;
  height: 1px;
  background: #c0a374;
}

.menu-card h1 {
  position: relative;
  z-index: 2;
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 0.72;
  letter-spacing: -0.055em;
  color: #fff8de;
  transform: rotate(-2deg);
  filter: drop-shadow(0 7px 0 #713b1c) drop-shadow(0 12px 14px rgba(100, 62, 20, 0.26));
}

.h1-top {
  font-size: clamp(39px, 6.5vw, 58px);
  color: #ffcf53;
  -webkit-text-stroke: 2px #904315;
  text-shadow: 0 4px 0 #904315;
  letter-spacing: 0.12em;
  padding-left: 0.12em;
}

.h1-main {
  font-size: clamp(66px, 11vw, 94px);
  -webkit-text-stroke: 3px #7e2a1b;
  text-shadow: 0 6px 0 #7e2a1b, 0 9px 0 #bb5d22;
}

.menu-card h1 em {
  display: inline-block;
  margin-top: 13px;
  padding: 4px 11px 5px;
  border-radius: 8px;
  background: #3f6d32;
  border: 2px solid #294a20;
  color: #fff7dc;
  font-size: 13px;
  font-style: normal;
  letter-spacing: 0.08em;
  transform: rotate(2deg);
  box-shadow: 0 3px 0 #1d3515;
}

.menu-tagline {
  max-width: 320px;
  margin: 22px auto 0;
  color: #715e3e;
  font-size: 12px;
  line-height: 1.5;
  font-weight: 700;
}

.feature-row {
  display: flex;
  justify-content: center;
  gap: 0;
  margin: 20px auto 18px;
  padding: 10px 0;
  border-top: 1px solid rgba(129, 98, 46, 0.16);
  border-bottom: 1px solid rgba(129, 98, 46, 0.16);
}

.feature-row div {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 33.33%;
  border-right: 1px solid rgba(129, 98, 46, 0.14);
}

.feature-row div:last-child {
  border: 0;
}

.feature-row strong {
  font-size: 23px;
  line-height: 1;
  color: #3a5228;
}

.feature-row span {
  font-size: 7px;
  letter-spacing: 0.17em;
  color: #9a8259;
  font-weight: 900;
}

.primary-btn {
  position: relative;
  display: block;
  width: 100%;
  max-width: 290px;
  margin: 0 auto;
  padding: 13px 24px 15px;
  border: 2px solid #9e4515;
  border-radius: 15px;
  background: linear-gradient(180deg, #ffbc55, #ff8a2e 48%, #dd5c17);
  color: #fffdf1;
  font-size: 19px;
  font-weight: 900;
  letter-spacing: 0.03em;
  text-shadow: 0 2px 0 rgba(113, 47, 9, 0.5);
  cursor: pointer;
  box-shadow: 0 5px 0 #8e3810, 0 10px 20px rgba(112, 52, 14, 0.3), inset 0 2px 0 rgba(255, 255, 255, 0.38);
  transition: transform 0.12s, filter 0.12s, box-shadow 0.12s;
}

.primary-btn:hover {
  filter: brightness(1.06);
  transform: translateY(-1px);
}

.primary-btn:active {
  transform: translateY(3px);
  box-shadow: 0 2px 0 #8e3810, inset 0 2px 0 rgba(255, 255, 255, 0.3);
}

.text-btn {
  margin-top: 12px;
  padding: 4px 8px;
  border: 0;
  background: none;
  color: #826c46;
  font-size: 10px;
  font-weight: 900;
  cursor: pointer;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.text-btn:hover {
  color: #4f3b20;
}

.best-line {
  margin-top: 16px;
  color: #a28b61;
  font-size: 7px;
  letter-spacing: 0.16em;
  font-weight: 900;
}

.best-line strong {
  margin-left: 5px;
  color: #5c4525;
  font-size: 9px;
}

.menu-hero-monkey {
  position: absolute;
  right: -34px;
  bottom: 32px;
  width: 100px;
  height: 105px;
  transform: rotate(7deg);
  filter: drop-shadow(0 8px 6px rgba(90, 55, 12, 0.22));
  pointer-events: none;
}

.mh-head {
  position: absolute;
  left: 20px;
  top: 15px;
  width: 61px;
  height: 61px;
  border-radius: 50%;
  background: linear-gradient(145deg, #9b6435, #6e3e20);
  border: 3px solid #553019;
}

.mh-ear {
  position: absolute;
  top: 11px;
  width: 23px;
  height: 25px;
  border-radius: 50%;
  background: #7c4925;
  border: 3px solid #553019;
}

.mh-ear.left {
  left: -18px;
}

.mh-ear.right {
  right: -18px;
}

.mh-face {
  position: absolute;
  left: 9px;
  top: 18px;
  width: 43px;
  height: 34px;
  border-radius: 50%;
  background: #f4c792;
}

.mh-face b {
  position: absolute;
  top: 10px;
  width: 6px;
  height: 8px;
  border-radius: 50%;
  background: #2d2013;
}

.mh-face b:first-child {
  left: 10px;
}

.mh-face b:nth-child(2) {
  right: 10px;
}

.mh-face s {
  position: absolute;
  left: 17px;
  bottom: 7px;
  width: 10px;
  height: 5px;
  border-bottom: 2px solid #7b4225;
  border-radius: 50%;
  text-decoration: none;
}

.mh-cap {
  position: absolute;
  left: -5px;
  top: -7px;
  width: 70px;
  height: 28px;
  border-radius: 50% 50% 22% 22%;
  background: linear-gradient(180deg, #5a9d42, #3b742d);
  border: 3px solid #2d571f;
  transform: rotate(-4deg);
}

.mh-cap::after {
  content: "";
  position: absolute;
  right: -20px;
  bottom: -2px;
  width: 29px;
  height: 10px;
  border-radius: 0 20px 20px 0;
  background: #4d8b38;
  border: 3px solid #2d571f;
}

.menu-footnote {
  position: absolute;
  bottom: 16px;
  margin: 0;
  color: rgba(255, 246, 221, 0.42);
  font-size: 9px;
  letter-spacing: 0.06em;
  font-weight: 700;
}

.menu-balloons {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.float-balloon {
  position: absolute;
  width: 42px;
  height: 52px;
  border-radius: 50% 50% 46% 46% / 55% 55% 44% 44%;
  background:
    radial-gradient(circle at 31% 25%, rgba(255, 255, 255, 0.9) 0 8%, transparent 9%),
    radial-gradient(circle at 38% 28%, rgba(255, 255, 255, 0.35) 0 19%, transparent 20%),
    var(--balloon, #e94b4f);
  box-shadow: inset -8px -11px 3px rgba(0, 0, 0, 0.15);
  opacity: 0.6;
  animation: balloonFloat 12s ease-in-out infinite;
}

.float-balloon::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 100%;
  width: 1px;
  height: 38px;
  background: rgba(255, 246, 220, 0.32);
}

.b1 { left: 10%; top: 24%; --balloon: #e94b4f; animation-delay: -1s; transform: rotate(-8deg) scale(1.2); }
.b2 { left: 17%; top: 68%; --balloon: #3f8ff0; animation-delay: -4s; transform: scale(0.8); }
.b3 { left: 84%; top: 18%; --balloon: #38b95d; animation-delay: -7s; transform: scale(0.9); }
.b4 { left: 78%; top: 64%; --balloon: #f2cf36; animation-delay: -2.4s; transform: rotate(9deg) scale(1.3); }
.b5 { left: 91%; top: 42%; --balloon: #fa72b8; animation-delay: -5.5s; transform: scale(0.7); }

.modal-screen {
  background: rgba(5, 19, 12, 0.64);
  backdrop-filter: blur(7px);
  animation: fadeIn 0.18s ease-out;
}

.modal-card {
  position: relative;
  width: min(640px, calc(100vw - 32px));
  max-height: calc(100svh - 40px);
  overflow: auto;
  padding: 30px 34px 28px;
  border-radius: 26px;
  border: 3px solid #76552b;
  background:
    radial-gradient(circle at 20% 10%, rgba(255, 255, 255, 0.72), transparent 20%),
    linear-gradient(155deg, #fff9e5, #f2dfb2);
  box-shadow: 0 6px 0 #4a3018, 0 28px 70px rgba(0, 0, 0, 0.5);
  animation: modalIn 0.24s cubic-bezier(0.2, 0.9, 0.3, 1.1) both;
  text-align: center;
}

.modal-close {
  position: absolute;
  right: 14px;
  top: 13px;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 10px;
  background: rgba(78, 56, 26, 0.08);
  color: #715633;
  font-size: 25px;
  cursor: pointer;
}

.modal-close:hover {
  background: rgba(78, 56, 26, 0.16);
}

.modal-eyebrow {
  font-size: 8px;
  letter-spacing: 0.2em;
  color: #a48452;
  font-weight: 900;
}

.modal-card h2 {
  margin: 6px 0 6px;
  font-size: clamp(26px, 4vw, 38px);
  letter-spacing: -0.04em;
  color: #384823;
}

.help-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin: 20px 0 16px;
  text-align: left;
}

.help-grid article {
  position: relative;
  padding: 14px 13px 12px 42px;
  border-radius: 13px;
  background: rgba(85, 107, 56, 0.07);
  border: 1px solid rgba(93, 76, 40, 0.1);
}

.help-number {
  position: absolute;
  left: 10px;
  top: 12px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 8px;
  background: #5a843d;
  color: #fff7dd;
  font-size: 11px;
  font-weight: 900;
  box-shadow: 0 2px 0 #385425;
}

.help-grid h3 {
  margin: 0 0 4px;
  font-size: 11px;
  color: #3e502a;
}

.help-grid p {
  margin: 0;
  font-size: 9px;
  line-height: 1.45;
  color: #7d6d4e;
  font-weight: 600;
}

.balloon-key {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 5px 12px;
