```
window.addEventListener('resize',()=> {
 setupCanvas(); // only if layout same; but if W/H fixed
 const shouldPortrait=detectPortrait();
 if ((shouldPortrait? 'portrait':'landscape')!==layoutVariant) {
   if (state.mode==='playing') {showToast('...'); return;}
   applyLayout(shouldPortrait,true); resetGame(state.mode==='menu'?'menu':state.mode); delete? ...
