});
```
But orientation change triggers resize before media query maybe; use media listener. Simpler:
```
let resizeTimer
window.addEventListener('resize',()=> {clearTimeout; setTimeout(()=>{ 
 const desired=detectPortrait();
 if ((desired?'portrait':'landscape')!==layoutVariant) {
   if (state.mode==='playing'){ showToast('Finish this round...'); return;}
   applyLayout(desired,true);
