const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser = await chromium.launch({headless:true});
 const page = await browser.newPage({viewport:{width:1440,height:900}});
 const errors=[]; page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002/?debug=1&t='+Date.now(), {waitUntil:'load'}); await page.waitForTimeout(300);
 const result = await page.evaluate(async()=>{
  const g=window.__bloonBlast;
  const core=await import('/src/core.js');
  const T=core.TOWER_TYPES;
  g.beginGame();
  const order=[['dart',340,450],['sniper',1000,400],['tack',1120,300],['bomb',420,330],['ice',980,200],['boomerang',1400,600],['super',1300,450]];
  const log=[];
  let idx=0;
  function spend(){
    let changed=true;
    while(changed){
      changed=false;
      // Prefer next tower until 4 towers, then upgrades.
      if(idx<order.length && g.state.towers.length<4){
        const [type,x,y]=order[idx];
        if(g.state.cash>=T[type].cost){ const t=g.placeTower(type,x,y); if(t){idx++;changed=true;continue;} }
      }
      // Buy cheapest next upgrade across all towers.
      let best=null;
      for(const t of g.state.towers){
        for(const path of ['top','bottom']){
          const lvl=t.levels[path];
          if(lvl>=3) continue;
          const cost=T[t.type].paths[path][lvl].cost;
          if(g.state.cash>=cost && (!best||cost<best.cost)) best={t,path,cost};
        }
      }
      if(best){ g.state.cash-=best.cost; best.t.levels[best.path]++; best.t.stats=g.getTowerStats(best.t.type,best.t.levels); changed=true; continue; }
      if(idx<order.length){
        const [type,x,y]=order[idx];
        if(g.state.cash>=T[type].cost){ const t=g.placeTower(type,x,y); if(t){idx++;changed=true;} }
      }
    }
  }
  spend();
  for(let w=0;w<30;w++){
    if(g.state.mode!=='playing') break;
    g.startRound();
    let steps=0;
    while(g.state.waveActive && g.state.mode==='playing' && steps<30000){ g.simulate(1/60); steps++; }
    log.push({round:g.state.waveIndex,lives:g.state.lives,cash:Math.round(g.state.cash),towers:g.state.towers.map(t=>t.type+':'+t.levels.top+'/'+t.levels.bottom),waveActive:g.state.waveActive,mode:g.state.mode});
    if(g.state.mode!=='playing') break;
    spend();
  }
  return {log,mode:g.state.mode,lives:g.state.lives,towers:g.state.towers.map(t=>({type:t.type,levels:t.levels})),pops:g.state.totalPops};
 });
 console.log(JSON.stringify(result,null,1));
 console.log('errors',errors);
 await browser.close();
})();
